// Requirements is the resolver for the requirements field.
func (r *deviceProfileResolver) Requirements(ctx context.Context, obj *graph.DeviceProfile) ([]*graph.DeviceProfileRequirement, error) {
	tc := tenant.MustGet(ctx)

	workspaceID, err := uuid.Parse(tc.TenantID)
	if err != nil {
		return nil, fmt.Errorf("invalid workspace id: %w", err)
	}

	profileID, err := uuid.Parse(obj.ID)
	if err != nil {
		return nil, fmt.Errorf("invalid profile id: %w", err)
	}

	requirements, err := r.PostureStore.ListRequirements(
		ctx,
		workspaceID,
		profileID,
	)
	if err != nil {
		return nil, fmt.Errorf("requirements: %w", err)
	}

	result := make([]*graph.DeviceProfileRequirement, len(requirements))
	for i, requirement := range requirements {
		result[i] = &graph.DeviceProfileRequirement{
			ID:               requirement.ID.String(),
			CheckID:          requirement.CheckID,
			AllowUnsupported: requirement.AllowUnsupported,
		}
		if requirement.Countries != nil {
			result[i].Countries = &graph.CountryRule{
				Allow: append([]string{}, requirement.Countries.Allow...),
				Deny:  append([]string{}, requirement.Countries.Deny...),
			}
		}
	}

	return result, nil
}

// Policies is the resolver for the policies field.
func (r *deviceProfileResolver) Policies(ctx context.Context, obj *graph.DeviceProfile) ([]*graph.ResourcePolicy, error) {
	ws, err := policyWorkspace(ctx)
	if err != nil {
		return nil, err
	}
	pid, ok := parsePolicyID(obj.ID)
	if !ok {
		return []*graph.ResourcePolicy{}, nil
	}
	refs, err := r.PostureStore.PoliciesUsingProfile(ctx, ws, pid)
	if err != nil {
		return nil, fmt.Errorf("profile policies: %w", err)
	}
	out := make([]*graph.ResourcePolicy, 0, len(refs))
	for _, ref := range refs {
		p, err := r.PostureStore.GetResourcePolicy(ctx, ws, ref.ID)
		if err != nil {
			return nil, fmt.Errorf("profile policies: %w", err)
		}
		out = append(out, resourcePolicyToGQL(p))
	}
	return out, nil
}

