// AddProfileRequirement is the resolver for the addProfileRequirement field.
func (r *mutationResolver) AddProfileRequirement(ctx context.Context, profileID string, checkID string, allowUnsupported bool, countries *graph.CountryRuleInput) (*graph.DeviceProfile, error) {
	tc := tenant.MustGet(ctx)

	workspaceID, err := uuid.Parse(tc.TenantID)
	if err != nil {
		return nil, fmt.Errorf("invalid workspace id: %w", err)
	}

	profileUUID, err := uuid.Parse(profileID)
	if err != nil {
		return nil, apperr.UserErrorf("invalid profile id")
	}

	if !posture.IsRecognizedCheck(checkID) {
		return nil, apperr.UserErrorf("unknown posture check: %s", checkID)
	}

	// PENDING-20 G1: the country check needs a rule; no other check takes one.
	var countryRule *posture.CountryRule
	switch {
	case checkID == posture.CheckNetworkCountry && allowUnsupported:
		return nil, apperr.UserErrorf("addProfileRequirement: allowUnsupported does not apply to the country check; an unknown location always denies")
	case checkID == posture.CheckNetworkCountry && countries == nil:
		return nil, apperr.UserErrorf("addProfileRequirement: the country check needs countries to allow or deny")
	case checkID != posture.CheckNetworkCountry && countries != nil:
		return nil, apperr.UserErrorf("addProfileRequirement: countries apply only to %s", posture.CheckNetworkCountry)
	case countries != nil:
		rule, err := posture.NormalizeCountryRule(posture.CountryRule{Allow: countries.Allow, Deny: countries.Deny})
		if err != nil {
			return nil, apperr.UserErrorf("addProfileRequirement: %v", err)
		}
		countryRule = &rule
	}

	err = r.PostureStore.AddRequirement(
		ctx,
		workspaceID,
		profileUUID,
		posture.Requirement{
			CheckID:          checkID,
			AllowUnsupported: allowUnsupported,
			Countries:        countryRule,
		},
	)
	if err != nil {
		switch {
		case errors.Is(err, posture.ErrDuplicateRequirement):
			return nil, apperr.UserErrorf("addProfileRequirement: duplicate requirement")
		case errors.Is(err, posture.ErrNotFound):
			return nil, apperr.UserErrorf("addProfileRequirement: profile not found")
		default:
			return nil, fmt.Errorf("addProfileRequirement: %w", err)
		}
	}

	auditDetails := map[string]any{"check_id": checkID, "allow_unsupported": allowUnsupported}
	if countryRule != nil {
		auditDetails["allow_countries"] = countryRule.Allow
		auditDetails["deny_countries"] = countryRule.Deny
	}
	r.auditAdmin(ctx, "device_profile.requirement.add", "device_profile", profileID, auditDetails)
	if err := r.PolicyNotifier.NotifyPolicyChange(ctx, tc.TenantID); err != nil {
		return nil, fmt.Errorf("addProfileRequirement notify: %w", err)
	}
	if r.PostureEvaluator == nil {
		return nil, fmt.Errorf("addProfileRequirement: posture evaluator is not configured")
	}
	if err := r.PostureEvaluator.ReevaluateWorkspace(ctx, workspaceID); err != nil {
		return nil, fmt.Errorf("addProfileRequirement re-evaluate: %w", err)
	}

	profile, err := r.PostureStore.GetProfile(
		ctx,
		workspaceID,
		profileUUID,
	)
	if err != nil {
		return nil, fmt.Errorf("addProfileRequirement: %w", err)
	}

	return postureProfileToGQL(profile), nil
}

// UpdateProfileRequirementCountries is the resolver for the updateProfileRequirementCountries field.
func (r *mutationResolver) UpdateProfileRequirementCountries(ctx context.Context, profileID string, countries graph.CountryRuleInput) (*graph.DeviceProfile, error) {
	tc := tenant.MustGet(ctx)
	workspaceID, err := uuid.Parse(tc.TenantID)
	if err != nil {
		return nil, fmt.Errorf("invalid workspace id: %w", err)
	}
	profileUUID, err := uuid.Parse(profileID)
	if err != nil {
		return nil, apperr.UserErrorf("invalid profile id")
	}
	rule, err := posture.NormalizeCountryRule(posture.CountryRule{Allow: countries.Allow, Deny: countries.Deny})
	if err != nil {
		return nil, apperr.UserErrorf("updateProfileRequirementCountries: %v", err)
	}
	previous, err := r.PostureStore.UpdateCountryRule(ctx, workspaceID, profileUUID, rule)
	if err != nil {
		if errors.Is(err, posture.ErrNotFound) {
			return nil, apperr.UserErrorf("updateProfileRequirementCountries: profile not found or it has no country check")
		}
		return nil, fmt.Errorf("updateProfileRequirementCountries: %w", err)
	}
	r.auditAdmin(ctx, "device_profile.requirement.countries_update", "device_profile", profileID, map[string]any{
		"check_id":            posture.CheckNetworkCountry,
		"allow_countries":     rule.Allow,
		"deny_countries":      rule.Deny,
		"old_allow_countries": previous.Allow,
		"old_deny_countries":  previous.Deny,
	})
	if err := r.PolicyNotifier.NotifyPolicyChange(ctx, tc.TenantID); err != nil {
		return nil, fmt.Errorf("updateProfileRequirementCountries notify: %w", err)
	}
	if r.PostureEvaluator == nil {
		return nil, fmt.Errorf("updateProfileRequirementCountries: posture evaluator is not configured")
	}
	if err := r.PostureEvaluator.ReevaluateWorkspace(ctx, workspaceID); err != nil {
		return nil, fmt.Errorf("updateProfileRequirementCountries re-evaluate: %w", err)
	}
	profile, err := r.PostureStore.GetProfile(ctx, workspaceID, profileUUID)
	if err != nil {
		return nil, fmt.Errorf("updateProfileRequirementCountries: %w", err)
	}
	return postureProfileToGQL(profile), nil
}

// DeleteDeviceProfile is the resolver for the deleteDeviceProfile field.
// PENDING-16 D-4: a profile that resource policies use is deleted only with
// confirmInUse; the store then removes it from them in the same transaction.
func (r *mutationResolver) DeleteDeviceProfile(ctx context.Context, id string, confirmInUse *bool) (bool, error) {
	tc := tenant.MustGet(ctx)

	workspaceID, err := uuid.Parse(tc.TenantID)
	if err != nil {
		return false, fmt.Errorf("invalid workspace id: %w", err)
	}

	profileUUID, err := uuid.Parse(id)
	if err != nil {
		return false, apperr.UserErrorf("invalid profile id")
	}

	result, err := r.PostureStore.DeleteProfile(ctx, workspaceID, profileUUID, confirmInUse != nil && *confirmInUse)
	if err != nil {
		var inUse *posture.ProfileInUseError
		switch {
		case errors.As(err, &inUse):
			return false, err // user-safe: names the policies
		case errors.Is(err, posture.ErrNotFound):
			return false, apperr.UserErrorf("deleteDeviceProfile: profile not found")
		default:
			return false, fmt.Errorf("deleteDeviceProfile: %w", err)
		}
	}

	r.auditAdmin(ctx, "device_profile.delete", "device_profile", id, map[string]any{
		"removed_from_policies":   policyRefNames(result.RemovedFrom),
		"policies_now_any_device": policyRefNames(result.NowAnyDevice),
	})
	if err := r.PolicyNotifier.NotifyPolicyChange(ctx, tc.TenantID); err != nil {
		return false, fmt.Errorf("deleteDeviceProfile notify: %w", err)
	}
	return true, nil
}

// RemoveProfileRequirement is the resolver for the removeProfileRequirement field.
func (r *mutationResolver) RemoveProfileRequirement(ctx context.Context, profileID string, checkID string) (*graph.DeviceProfile, error) {
	tc := tenant.MustGet(ctx)

	workspaceID, err := uuid.Parse(tc.TenantID)
	if err != nil {
		return nil, fmt.Errorf("invalid workspace id: %w", err)
	}

	profileUUID, err := uuid.Parse(profileID)
	if err != nil {
		return nil, apperr.UserErrorf("invalid profile id")
	}

	if !posture.IsRecognizedCheck(checkID) {
		return nil, apperr.UserErrorf("unknown posture check: %s", checkID)
	}

	err = r.PostureStore.RemoveRequirement(
		ctx,
		workspaceID,
		profileUUID,
		checkID,
	)
	if err != nil {
		switch {
		case errors.Is(err, posture.ErrLastRequirement):
			return nil, err // user-safe

		case errors.Is(err, posture.ErrNotFound):
			return nil, apperr.UserErrorf(
				"removeProfileRequirement: requirement or profile not found",
			)

		default:
			return nil, fmt.Errorf(
				"removeProfileRequirement: %w",
				err,
			)
		}
	}

	r.auditAdmin(ctx, "device_profile.requirement.remove", "device_profile", profileID, map[string]any{"check_id": checkID})
	if err := r.PolicyNotifier.NotifyPolicyChange(
		ctx,
		tc.TenantID,
	); err != nil {
		return nil, fmt.Errorf(
			"removeProfileRequirement notify: %w",
			err,
		)
	}
	if r.PostureEvaluator == nil {
		return nil, fmt.Errorf("removeProfileRequirement: posture evaluator is not configured")
	}
	if err := r.PostureEvaluator.ReevaluateWorkspace(ctx, workspaceID); err != nil {
		return nil, fmt.Errorf("removeProfileRequirement re-evaluate: %w", err)
	}

	profile, err := r.PostureStore.GetProfile(
		ctx,
		workspaceID,
		profileUUID,
	)
	if err != nil {
		return nil, fmt.Errorf(
			"removeProfileRequirement: %w",
			err,
		)
	}

	return postureProfileToGQL(profile), nil
}

// SupportedPostureChecks is the resolver for the supportedPostureChecks field.
func (r *queryResolver) SupportedPostureChecks(ctx context.Context) ([]*graph.PostureCheckDescriptor, error) {
	checks := posture.SupportedCheckDescriptors()

	result := make([]*graph.PostureCheckDescriptor, len(checks))
	for i, check := range checks {
		result[i] = &graph.PostureCheckDescriptor{
			ID:                         check.ID,
			Label:                      check.Label,
			Platform:                   check.Platform,
			AllowUnsupportedMeaningful: check.AllowUnsupportedMeaningful,
		}
	}

	return result, nil
}

